  if(frame.customItems!==undefined&&(!dense(frame.customItems)||canonical(frame.customItems)===null||frame.customItems.some(value=>names.includes(Array.isArray(value)?value[0]:value?.n))))return fail('original-unmodified-instrument-required');
  return {ok:true,profileId:p.id,profile:p.id,itemFingerprint:p.itemFingerprint,grantsFingerprint:p.grantsFingerprint,parentFingerprint:generic?INSTRUMENT_GENERIC_FINGERPRINT:null,physicalId:marker.id,grants:copy(p.grants)};
